-- ================================================================
-- antique 商城种子数据(开发/演示环境)
-- 生成日期: 2026-08-14
--
-- 数据规模:
--   user             59 条新增(id 2~61,id=1 为现有账号「拾酒」,不动)
--   antique          60 条(id 1~60,五大分类各 10~15 条)
--   favorite         55 条(user_id / antique_id 均为有效外键,无重复对)
--   user_sign_record 55 条(2026-08 签到流水)
--
-- 一致性说明(保证"不假"):
--   1. antique.like_count 不手写,末尾由 favorite 表统计回写,与收藏记录严格对账
--   2. user.points / sign_in_days / last_sign_date 与签到流水严格一致:
--      points = Σ(points_earned),sign_in_days = 截至最后签到日的连续天数,
--      断签用户连续天数归 0(与个人中心展示口径一致)
--   3. 手机号均为合法 11 位且不重复;用户 2~6 配置了密码登录账号,
--      密码统一为 123456(BCrypt 加密,可直接用 /api/user/login/password 登录测试)
--   4. 图片使用 picsum.photos 稳定占位图,正式环境替换为 OSS 地址即可
--
-- 执行方式:
--   mysql -uroot -p antique --default-character-set=utf8mb4 -e "source sql/seed-data.sql"
--
-- 注意: 表内已有数据时请勿直接执行(主键冲突),如需重置请先清空四张表
-- ================================================================

USE antique;
SET NAMES utf8mb4;

-- ================================================================
-- 1. user 表:59 条(id 2~61)
--    2~6 有密码(123456);39~43 为微信登录(openid);21~24 断签;25~61 未签到
-- ================================================================

