-- ================================================================
-- 5. 回写 like_count:收藏数 = favorite 表统计(保证对账一致)
-- ================================================================
UPDATE `antique` a
SET a.`like_count` = (SELECT COUNT(*) FROM `favorite` f WHERE f.`antique_id` = a.`id`);

-- ================================================================
-- 6. 执行后自检(核对无误后可删除此段)
-- ================================================================
SELECT '行数自检' AS check_name,
       (SELECT COUNT(*) FROM `user`) AS user_cnt,
       (SELECT COUNT(*) FROM `antique`) AS antique_cnt,
       (SELECT COUNT(*) FROM `favorite`) AS favorite_cnt,
       (SELECT COUNT(*) FROM `user_sign_record`) AS sign_cnt;
