(1,  '青花缠枝莲纹将军罐', 1, '青花瓷', '清代乾隆', '瓷器', 68000.00, 'https://picsum.photos/seed/antique1/600/450', '["https://picsum.photos/seed/antique1-1/600/450","https://picsum.photos/seed/antique1-2/600/450"]', '口径22cm,高42cm,底书"大清乾隆年制"六字三行篆书款。青花发色浓艳沉稳,缠枝莲纹舒展流畅,釉面肥润,全品无冲无裂,罐盖完整。', 2, '永和堂古玩', 1568, 0, 1, 1, '2025-12-06 10:23:41', '2025-12-06 10:23:41'),
(2,  '青花釉里红岁寒三友纹梅瓶', 1, '青花瓷', '明代宣德', '瓷器', 268000.00, 'https://picsum.photos/seed/antique2/600/450', '["https://picsum.photos/seed/antique2-1/600/450","https://picsum.photos/seed/antique2-2/600/450"]', '高38cm,釉里红发色纯正,红蓝交映成趣。口沿微磕一处(已修复),余全品,传世包浆自然,梅瓶大器,陈设雅室。', 2, '永和堂古玩', 986, 0, 0, 1, '2025-12-10 14:32:17', '2025-12-10 14:32:17'),
(3,  '斗彩鸡缸杯一对(民国仿)', 1, '斗彩', '民国', '瓷器', 32000.00, 'https://picsum.photos/seed/antique3/600/450', '["https://picsum.photos/seed/antique3-1/600/450","https://picsum.photos/seed/antique3-2/600/450"]', '口径8.3cm,成对保存,民国景德镇仿成化,胎薄釉润,画工精细,底书"大明成化年制"六字款。', 3, '聚宝轩', 412, 0, 0, 1, '2025-12-15 09:15:03', '2025-12-15 09:15:03'),
(4,  '龙泉窑青釉刻花碗', 1, '青釉', '宋代', '瓷器', 88000.00, 'https://picsum.photos/seed/antique4/600/450', '["https://picsum.photos/seed/antique4-1/600/450","https://picsum.photos/seed/antique4-2/600/450"]', '口径17cm,釉色梅子青,内壁刻花莲瓣纹,足底露胎处火石红自然,开片细密,宋韵十足。', 3, '聚宝轩', 2134, 0, 1, 1, '2025-12-20 16:48:55', '2025-12-20 16:48:55'),
(5,  '钧窑天蓝釉红斑三足炉', 1, '钧窑', '金代', '瓷器', 98000.00, 'https://picsum.photos/seed/antique5/600/450', '["https://picsum.photos/seed/antique5-1/600/450","https://picsum.photos/seed/antique5-2/600/450"]', '口径12cm,天蓝釉配玫瑰紫红斑,窑变瑰丽无双,炉身微有开片,底有支烧痕迹,香道佳器。', 4, '古月斋', 1876, 0, 1, 1, '2025-12-26 11:06:32', '2025-12-26 11:06:32'),
(6,  '汝窑天青釉水仙盆(民国仿)', 1, '汝窑', '民国', '瓷器', 15000.00, 'https://picsum.photos/seed/antique6/600/450', '["https://picsum.photos/seed/antique6-1/600/450","https://picsum.photos/seed/antique6-2/600/450"]', '民国仿汝,天青釉面开细密冰裂纹,支钉烧痕齐全,文房陈设雅器,釉色温润可人。', 4, '古月斋', 356, 0, 0, 1, '2026-01-02 15:27:48', '2026-01-02 15:27:48'),
(7,  '青花人物故事图大罐', 1, '青花瓷', '清代康熙', '瓷器', 126000.00, 'https://picsum.photos/seed/antique7/600/450', '["https://picsum.photos/seed/antique7-1/600/450","https://picsum.photos/seed/antique7-2/600/450"]', '高36cm,绘西厢记人物故事,青花分水层次分明,俗称"康熙蓝",釉面莹润,传世品相。', 5, '听雨楼', 764, 0, 0, 1, '2026-01-08 10:53:14', '2026-01-08 10:53:14'),
(8,  '五彩龙凤纹大盘', 1, '五彩', '清代康熙', '瓷器', 78000.00, 'https://picsum.photos/seed/antique8/600/450', '["https://picsum.photos/seed/antique8-1/600/450","https://picsum.photos/seed/antique8-2/600/450"]', '口径40cm,康熙五彩,色彩浓艳,龙凤呈祥纹饰,盘沿轻微脱彩,底书"大清康熙年制"楷书款。', 5, '听雨楼', 1203, 0, 0, 2, '2026-01-14 13:41:27', '2026-01-14 13:41:27'),
(9,  '白釉暗刻龙纹天球瓶', 1, '白釉', '清代雍正', '瓷器', 66000.00, 'https://picsum.photos/seed/antique9/600/450', '["https://picsum.photos/seed/antique9-1/600/450","https://picsum.photos/seed/antique9-2/600/450"]', '高32cm,雍正白釉,釉色洁白温润,暗刻云龙纹,对光隐现,工艺含蓄内敛。', 6, '静心阁', 623, 0, 0, 1, '2026-01-20 09:22:36', '2026-01-20 09:22:36'),
